import { strokeWorldWidth } from "./stroke";

export const FONT_FAMILY = "system-ui, sans-serif";

export const LINE_HEIGHT = 1.3;

export const MIN_TEXT_PX = 1.5;

const MEASURE_PX = 100;

export type Measure = (text: string) => number;

export const canvasFont = (px: number): string => `${px}px ${FONT_FAMILY}`;

export const measureText =
  (ctx: CanvasRenderingContext2D, px: number): Measure =>
  (text) => {
    ctx.font = canvasFont(px);
    return ctx.measureText(text).width;
  };

const breakWord = (word: string, maxWidth: number, measure: Measure): string[] => {
  const pieces: string[] = [];
  let piece = "";
  for (const char of word) {
    if (piece !== "" && measure(piece + char) > maxWidth) {
      pieces.push(piece);
      piece = char;
      continue;
    }
    piece += char;
  }
  if (piece !== "") pieces.push(piece);
  return pieces;
};

export const wrapText = (text: string, maxWidth: number, measure: Measure): string[] => {
  const lines: string[] = [];
  for (const paragraph of text.split("\n")) {
    let line = "";
    for (const token of paragraph.match(/\s*\S+\s*|\s+/g) ?? []) {
      if (measure((line + token).trimEnd()) <= maxWidth) {
        line += token;
        continue;
      }
      if (line.trimEnd() !== "") lines.push(line.trimEnd());
      line = "";
      const pieces = breakWord(token.trimEnd(), maxWidth, measure);
      const last = pieces.pop() ?? "";
      lines.push(...pieces);
      line = last + token.slice(token.trimEnd().length);
    }
    lines.push(line.trimEnd());
  }
  return lines;
};

export const wrapWorld = (
  text: string,
  width: number,
  font: number,
  measureAt: (px: number) => Measure,
): string[] => wrapText(text, (width / font) * MEASURE_PX, measureAt(MEASURE_PX));

export const worldFont = (object: { width: number; nativeZoom: number }): number =>
  strokeWorldWidth(object.width, object.nativeZoom);

export const clampFont = (width: number): number => Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, width));

export const fontForScreen = (px: number, nativeZoom: number, zoom: number): number =>
  clampFont(px / strokeWorldWidth(1, nativeZoom) / zoom);

export const paintLines = (
  ctx: CanvasRenderingContext2D,
  lines: readonly string[],
  origin: { x: number; y: number },
  px: number,
  colour: string,
): void => {
  if (px < MIN_TEXT_PX) return;
  ctx.fillStyle = colour;
  ctx.font = canvasFont(px);
  ctx.textBaseline = "middle";
  lines.forEach((line, index) => {
    ctx.fillText(line, origin.x, origin.y + (index + 0.5) * LINE_HEIGHT * px);
  });
};
import { DEFAULT_STROKE_STYLE, STROKE_STYLES, type StrokeStyle } from "@stallion/schema";

export const WIDE_QUERY = "(min-width: 960px)";

export const EXPANDED_KEY = "stallion:toolbar-expanded";

export const MODE_KEY = "stallion:toolbar-mode";

export const STYLE_KEY = "stallion:stroke-style";

export const RECENT_COLOURS_KEY = "stallion:recent-colours";

export const MAX_RECENT_COLOURS = 8;

export type ToolbarMode = "Quick" | "Palette";

export type Control =
  | "Sizes"
  | "Width"
  | "Styles"
  | "Shapes"
  | "Colours"
  | "CustomColour"
  | "RecentColours"
  | "CurrentColour"
  | "Pencil"
  | "Sticky"
  | "Text"
  | "Pan"
  | "Select"
  | "Eraser"
  | "Swap"
  | "Undo"
  | "Redo"
  | "Share"
  | "Level"
  | "Connection"
  | "Expand"
  | "Flip";

export type ToolbarLayout = "Wide" | "Collapsed" | "Expanded" | "Palette";

const WIDE_ROW: readonly Control[] = [
  "Sizes",
  "Colours",
  "Pan",
  "Select",
  "Sticky",
  "Text",
  "Eraser",
  "Swap",
  "Undo",
  "Redo",
  "Share",
  "Level",
  "Connection",
  "Flip",
];

const COLLAPSED_ROW: readonly Control[] = [
  "CurrentColour",
  "Pencil",
  "Eraser",
  "Undo",
  "Level",
  "Connection",
  "Expand",
];

const EXPANDED_ROWS: readonly (readonly Control[])[] = [
  COLLAPSED_ROW,
  ["Sizes", "Pan", "Select", "Redo", "Share"],
  ["Colours", "Swap"],
  ["Shapes", "Sticky", "Text", "Flip"],
];

const PALETTE_ROWS: readonly (readonly Control[])[] = [
  ["Flip", "Connection"],
  ["Sizes"],
  ["Width"],
  ["Styles"],
  ["Shapes"],
  ["Colours"],
  ["CustomColour", "RecentColours"],
  ["Swap", "Pan", "Select", "Eraser", "Sticky", "Text"],
  ["Undo", "Redo"],
  ["Level", "Share"],
];

export const toolbarLayout = (
  mode: ToolbarMode,
  wide: boolean,
  expanded: boolean,
): ToolbarLayout => {
  if (mode === "Palette") return "Palette";
  if (wide) return "Wide";
  return expanded ? "Expanded" : "Collapsed";
};

export const toolbarRows = (layout: ToolbarLayout): readonly (readonly Control[])[] => {
  if (layout === "Wide") return [WIDE_ROW];
  if (layout === "Collapsed") return [COLLAPSED_ROW];
  if (layout === "Palette") return PALETTE_ROWS;
  return EXPANDED_ROWS;
};

export const expandedAfterPick = (wide: boolean, expanded: boolean): boolean =>
  wide ? expanded : false;

type Store = Pick<Storage, "getItem" | "setItem">;

export const loadExpanded = (store: () => Store): boolean => {
  try {
    return store().getItem(EXPANDED_KEY) === "1";
  } catch {
    return false;
  }
};

export const saveExpanded = (store: () => Store, expanded: boolean): void => {
  try {
    store().setItem(EXPANDED_KEY, expanded ? "1" : "0");
  } catch {
    return;
  }
};

export const loadMode = (store: () => Store): ToolbarMode => {
  try {
    return store().getItem(MODE_KEY) === "Palette" ? "Palette" : "Quick";
  } catch {
    return "Quick";
  }
};

export const saveMode = (store: () => Store, mode: ToolbarMode): void => {
  try {
    store().setItem(MODE_KEY, mode);
  } catch {
    return;
  }
};

const isStrokeStyle = (value: unknown): value is StrokeStyle =>
  STROKE_STYLES.some((style) => style === value);

export const loadStyle = (store: () => Store): StrokeStyle => {
  try {
    const stored = store().getItem(STYLE_KEY);
    return isStrokeStyle(stored) ? stored : DEFAULT_STROKE_STYLE;
  } catch {
    return DEFAULT_STROKE_STYLE;
  }
};

export const saveStyle = (store: () => Store, style: StrokeStyle): void => {
  try {
    store().setItem(STYLE_KEY, style);
  } catch {
    return;
  }
};

const isRgb = (value: unknown): value is number =>
  Number.isInteger(value) && (value as number) >= 0 && (value as number) <= 0xffffff;

export const loadRecentColours = (store: () => Store): number[] => {
  try {
    const parsed: unknown = JSON.parse(store().getItem(RECENT_COLOURS_KEY) ?? "[]");
    return Array.isArray(parsed) ? parsed.filter(isRgb).slice(0, MAX_RECENT_COLOURS) : [];
  } catch {
    return [];
  }
};

export const withRecentColour = (recents: readonly number[], rgb: number): number[] =>
  [rgb, ...recents.filter((entry) => entry !== rgb)].slice(0, MAX_RECENT_COLOURS);

export const saveRecentColours = (store: () => Store, recents: readonly number[]): void => {
  try {
    store().setItem(RECENT_COLOURS_KEY, JSON.stringify(recents));
  } catch {
    return;
  }
};

export type Placement = { side: "Below" | "Above"; maxHeight: number };

export const POPOVER_GAP = 10;
export const VIEWPORT_GUTTER = 16;

export const placePopover = (
  anchor: { top: number; bottom: number },
  viewportHeight: number,
  desiredHeight: number,
): Placement => {
  const below = viewportHeight - anchor.bottom - POPOVER_GAP - VIEWPORT_GUTTER;
  const above = anchor.top - POPOVER_GAP - VIEWPORT_GUTTER;
  const side = below >= desiredHeight || below >= above ? "Below" : "Above";
  const room = side === "Below" ? below : above;
  return { side, maxHeight: Math.max(0, Math.floor(Math.min(desiredHeight, room))) };
};
import { expect, test } from "vitest";
import {
  expandedAfterPick,
  loadMode,
  loadRecentColours,
  loadStyle,
  MODE_KEY,
  placePopover,
  RECENT_COLOURS_KEY,
  STYLE_KEY,
  saveMode,
  saveRecentColours,
  saveStyle,
  toolbarLayout,
  toolbarRows,
  withRecentColour,
} from "./toolbar-layout";

const memoryStore = () => {
  const items = new Map<string, string>();
  return {
    getItem: (key: string) => items.get(key) ?? null,
    setItem: (key: string, value: string) => {
      items.set(key, value);
    },
  };
};

const broken = () => {
  throw new Error("storage blocked");
};

test("the collapsed bar is one row of the everyday controls and the toggle", () => {
  expect(toolbarRows(toolbarLayout("Quick", false, false))).toEqual([
    ["CurrentColour", "Pencil", "Eraser", "Undo", "Level", "Connection", "Expand"],
  ]);
});

test("the expanded bar adds sizes, colours, the other tools and the palette flip", () => {
  const rows = toolbarRows(toolbarLayout("Quick", false, true));
  expect(rows.length).toBeLessThanOrEqual(4);
  expect(rows.flat()).toEqual(
    expect.arrayContaining([
      "Sizes",
      "Colours",
      "Pan",
      "Select",
      "Redo",
      "Share",
      "Swap",
      "Shapes",
      "Flip",
    ]),
  );
});

test("a wide screen shows every tool and the flip on one row without a toggle", () => {
  const rows = toolbarRows(toolbarLayout("Quick", true, false));
  expect(rows).toHaveLength(1);
  expect(rows[0]).not.toContain("Expand");
  expect(rows[0]).toEqual(expect.arrayContaining(["Sizes", "Colours", "Redo", "Share", "Flip"]));
});

test("the palette holds every tool and the flip back, on any screen, without a toggle", () => {
  for (const wide of [false, true]) {
    for (const expanded of [false, true]) {
      const controls = toolbarRows(toolbarLayout("Palette", wide, expanded)).flat();
      expect(controls).toEqual(
        expect.arrayContaining([
          "Flip",
          "Sizes",
          "Width",
          "Styles",
          "Shapes",
          "Colours",
          "CustomColour",
          "RecentColours",
          "Swap",
          "Pan",
          "Select",
          "Eraser",
          "Undo",
          "Redo",
          "Level",
          "Share",
          "Connection",
        ]),
      );
      expect(controls).not.toContain("Expand");
    }
  }
});

test("the toolbar mode round-trips through storage and defaults to the quick bar", () => {
  const store = memoryStore();
  expect(loadMode(() => store)).toBe("Quick");
  saveMode(() => store, "Palette");
  expect(store.getItem(MODE_KEY)).toBe("Palette");
  expect(loadMode(() => store)).toBe("Palette");
  saveMode(() => store, "Quick");
  expect(loadMode(() => store)).toBe("Quick");
  store.setItem(MODE_KEY, "Sideways");
  expect(loadMode(() => store)).toBe("Quick");
});

test("blocked storage falls back to the quick bar and saving does not throw", () => {
  expect(loadMode(broken)).toBe("Quick");
  expect(() => saveMode(broken, "Palette")).not.toThrow();
});

test("the stroke style round-trips through storage and defaults to Pen", () => {
  const store = memoryStore();
  expect(loadStyle(() => store)).toBe("Pen");
  saveStyle(() => store, "Highlighter");
  expect(store.getItem(STYLE_KEY)).toBe("Highlighter");
  expect(loadStyle(() => store)).toBe("Highlighter");
  store.setItem(STYLE_KEY, "Marker");
  expect(loadStyle(() => store)).toBe("Pen");
  expect(loadStyle(broken)).toBe("Pen");
  expect(() => saveStyle(broken, "Dashed")).not.toThrow();
});

test("picking a colour collapses the bar on a narrow screen and not on a wide one", () => {
  expect(expandedAfterPick(false, true)).toBe(false);
  expect(expandedAfterPick(true, true)).toBe(true);
});

test("a popover flips above its anchor when there is no room below", () => {
  expect(placePopover({ top: 12, bottom: 68 }, 844, 440)).toEqual({
    side: "Below",
    maxHeight: 440,
  });
  expect(placePopover({ top: 780, bottom: 820 }, 844, 440)).toEqual({
    side: "Above",
    maxHeight: 440,
  });
  expect(placePopover({ top: 300, bottom: 344 }, 500, 440)).toEqual({
    side: "Above",
    maxHeight: 274,
  });
});

test("recent colours keep the last 8 distinct picks, newest first, and survive blocked storage", () => {
  const store = memoryStore();
  let recents: number[] = [];
  for (const rgb of [1, 2, 3, 4, 5, 6, 7, 8, 9, 3]) recents = withRecentColour(recents, rgb);
  expect(recents).toEqual([3, 9, 8, 7, 6, 5, 4, 2]);
  saveRecentColours(() => store, recents);
  expect(loadRecentColours(() => store)).toEqual(recents);
  store.setItem(RECENT_COLOURS_KEY, '[1, -1, 16777216, "x", 2]');
  expect(loadRecentColours(() => store)).toEqual([1, 2]);
  expect(loadRecentColours(broken)).toEqual([]);
  expect(() => saveRecentColours(broken, recents)).not.toThrow();
});

