import { writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";
import { routeAccessHeaders } from "../npm-scripts/env.mjs";

const [stage, origin = "https://stallion.matthijs-f49.workers.dev"] = process.argv.slice(2);
const DIR = join(homedir(), "development", ".tmp", "stallion-polish");
const boardId = () => `polish${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
const problems = [];

const open = async (browser, options) => {
  const context = await browser.newContext({ colorScheme: "light", ...options });
  await routeAccessHeaders(context, origin);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && problems.push(`console: ${m.text()}`));
  page.on("pageerror", (e) => problems.push(`pageerror: ${e.message}`));
  await page.goto(`${origin}/b/${boardId()}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(1500);
  return { context, page };
};
const save = async (page, name, clip) => {
  const path = join(DIR, `${stage}-${name}.png`);
  writeFileSync(path, await page.screenshot(clip ? { clip } : {}));
  console.log(path);
};
const toolbarClip = async (page) => {
  const box = await page.locator(".toolbar").boundingBox();
  return { x: 0, y: 0, width: page.viewportSize().width, height: Math.ceil(box.y + box.height + 12) };
};
const tap = async (page, point) => {
  const cdp = await page.context().newCDPSession(page);
  const touch = (type, p) =>
    cdp.send("Input.dispatchTouchEvent", {
      type,
      touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [],
    });
  await touch("touchStart", point);
  await touch("touchEnd");
  await cdp.detach();
};

const browser = await chromium.launch({ headless: true });
try {
  for (const width of [960, 1440]) {
    const { context, page } = await open(browser, { viewport: { width, height: 800 } });
    const box = await page.locator(".toolbar").boundingBox();
    const rows = await page.locator(".toolbar .toolbar-row").count();
    console.log(`desktop ${width}: toolbar ${Math.round(box.width)} px wide, ${rows} row(s), x ${Math.round(box.x)}`);
    await save(page, `desktop-${width}`, await toolbarClip(page));
    await context.close();
  }

  {
    const { context, page } = await open(browser, devices["Galaxy Tab S9"]);
    await page.locator("[data-toolbar-flip]").first().tap();
    await page.waitForTimeout(500);
    const box = await page.locator(".toolbar").boundingBox();
    await save(page, "tablet-palette", { x: 0, y: 0, width: Math.ceil(box.x + box.width + 16), height: Math.ceil(box.y + box.height + 16) });
    await context.close();
  }

  {
    const { context, page } = await open(browser, devices["Pixel 7"]);
    const more = page.getByRole("button", { name: "More tools" });
    if (await more.isVisible()) await more.tap();
    await page.getByRole("button", { name: "Sticky note" }).tap();
    const fewer = page.getByRole("button", { name: "Fewer tools" });
    if (await fewer.isVisible()) await fewer.tap();
    await page.waitForTimeout(300);
    const width = page.viewportSize().width;
    const bar = await page.locator(".toolbar").boundingBox();
    await tap(page, { x: Math.round(width / 2), y: Math.round(bar.y + bar.height + 60) });
    const editor = page.locator(".sticky-editor:not(.idle)");
    await editor.waitFor({ state: "visible", timeout: 5000 });
    await page.keyboard.type("Under the toolbar");
    await page.waitForTimeout(600);
    const note = await editor.boundingBox();
    const barNow = await page.locator(".toolbar").boundingBox();
    const done = await page.getByRole("button", { name: "Done" }).boundingBox();
    console.log(
      `phone: toolbar bottom ${Math.round(barNow.y + barNow.height)}, editor top ${Math.round(note.y)}, Done at ${Math.round(done.y)}..${Math.round(done.y + done.height)}`,
    );
    await save(page, "phone-editor-under-toolbar");
    await page.getByRole("button", { name: "Done" }).tap();
    await page.waitForTimeout(500);
    await context.close();
  }

  {
    const { context, page } = await open(browser, devices["Galaxy Tab S9"]);
    const more = page.getByRole("button", { name: "More tools" });
    if (await more.isVisible()) await more.tap();
    await page.getByRole("button", { name: "Text tool" }).tap();
    const fewer = page.getByRole("button", { name: "Fewer tools" });
    if (await fewer.isVisible()) await fewer.tap();
    await page.waitForTimeout(300);
    const at = { x: 200, y: 400 };
    await tap(page, at);
    await page.locator(".sticky-editor:not(.idle)").waitFor({ state: "visible", timeout: 5000 });
    await page.keyboard.type("hi");
    await page.getByRole("button", { name: "Done" }).tap();
    await page.waitForTimeout(500);
    if (await more.isVisible()) await more.tap();
    await page.getByRole("button", { name: "Select tool" }).tap();
    if (await fewer.isVisible()) await fewer.tap();
    await page.waitForTimeout(300);
    await tap(page, { x: at.x + 250, y: at.y });
    await page.waitForTimeout(300);
    await save(page, "text-tap-past-word", { x: 120, y: 320, width: 520, height: 160 });
    await tap(page, { x: at.x + 8, y: at.y });
    await page.waitForTimeout(300);
    await save(page, "text-selected", { x: 120, y: 320, width: 520, height: 160 });
    await context.close();
  }
} finally {
  await browser.close();
}
console.log(problems.length === 0 ? "console errors: 0" : `console errors:\n${problems.join("\n")}`);
EOF
